# Fixed version: check if component has neighbor with value 1
def solve_fixed(grid, height, width):
    result = [row[:] for row in grid]

    # First pass: iteratively fill rows/cols with 2+ ones
    changed = True
    while changed:
        changed = False

        rows_to_fill = set()
        cols_to_fill = set()

        for r in range(height):
            cnt = sum(1 for c in range(width) if result[r][c] == 1)
            if cnt >= 2:
                rows_to_fill.add(r)

        for c in range(width):
            cnt = sum(1 for r in range(height) if result[r][c] == 1)
            if cnt >= 2:
                cols_to_fill.add(c)

        for r in rows_to_fill:
            for c in range(width):
                if result[r][c] != 1:
                    result[r][c] = 1

        for c in cols_to_fill:
            for r in range(height):
                if result[r][c] != 1:
                    result[r][c] = 1

    visited = [[False]*width for _ in range(height)]

    def bfs_component(sr, sc):
        comp = []
        queue = [(sr, sc)]
        visited[sr][sc] = True
        while queue:
            r, c = queue.pop(0)
            comp.append((r,c))
            for nr, nc in [(r+1,c), (r-1,c), (r,c+1), (r,c-1)]:
                if 0 <= nr < height and 0 <= nc < width:
                    if not visited[nr][nc] and result[nr][nc] == 2:
                        visited[nr][nc] = True
                        queue.append((nr, nc))
        return comp

    # Convert each component that touches (is adjacent to) a cell with value 1
    for r in range(height):
        for c in range(width):
            if result[r][c] == 2 and not visited[r][c]:
                comp = bfs_component(r, c)
                # Check if component is adjacent to any cell with value 1
                touches_one = any(result[cr + dr][cc + dc] == 1 
                                 for cr, cc in comp 
                                 for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)])
                if touches_one:
                    for cr, cc in comp:
                        result[cr][cc] = 1

    return result

