# Add convergence detection
def solve_row_col_converge(grid, height, width):
    result = [row[:] for row in grid]

    prev_result = None

    changed = True
    iteration = 0

    while changed:
        changed = False
        iteration += 1

        prev_result = [row[:] for row in result]

        rows_to_fill = set()
        cols_to_fill = set()

        for r in range(height):
            cnt = sum(1 for c in range(width) if result[r][c] == 1)
            if cnt >= 2:
                rows_to_fill.add(r)

        for c in range(width):
            cnt = sum(1 for r in range(height) if result[r][c] == 1)
            if cnt >= 2:
                cols_to_fill.add(c)

        for r in sorted(rows_to_fill):
            for c in range(width):
                if result[r][c] != 1:
                    result[r][c] = 1

        for c in sorted(cols_to_fill):
            for r in range(height):
                if result[r][c] != 1:
                    result[r][c] = 1

        # Check for actual changes
        for r in range(height):
            for c in range(width):
                if prev_result[r][c] != result[r][c]:
                    changed = True
                    break
            if changed:
                break

        print(f"Iteration {iteration}: rows={sorted(rows_to_fill)}, cols={sorted(cols_to_fill)}, changed={changed}")

        if iteration > 30:
            print("Max iterations")
            break

    return result

