# Add 2->1 conversion for adjacent components
def solve_full_with_conversion(grid, height, width):
    result = [row[:] for row in grid]

    # Step 1: Converge row/col fills
    changed = True
    while changed:
        prev_result = [row[:] for row in result]

        rows_to_fill = set()
        cols_to_fill = set()

        for r in range(height):
            cnt = sum(1 for c in range(width) if result[r][c] == 1)
            if cnt >= 2:
                rows_to_fill.add(r)

        for c in range(width):
            cnt = sum(1 for r in range(height) if result[r][c] == 1)
            if cnt >= 2:
                cols_to_fill.add(c)

        for r in sorted(rows_to_fill):
            for c in range(width):
                if result[r][c] != 1:
                    result[r][c] = 1

        for c in sorted(cols_to_fill):
            for r in range(height):
                if result[r][c] != 1:
                    result[r][c] = 1

        changed = False
        for r in range(height):
            for c in range(width):
                if prev_result[r][c] != result[r][c]:
                    changed = True
                    break
            if changed:
                break

    # Step 2: Convert 2-components adjacent to 1s
    visited = [[False]*width for _ in range(height)]

    def get_component(comp_cells):
        """Get all 2s connected to comp_cells"""
        seen = set(comp_cells)
        result = list(comp_cells)
        queue = list(comp_cells)

        while queue:
            r, c = queue.pop(0)
            for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
                nr, nc = r+dr, c+dc
                if 0 <= nr < height and 0 <= nc < width:
                    if not visited[nr][nc] and result[nr][nc] == 2:
                        visited[nr][nc] = True
                        queue.append((nr, nc))
                        result.append((nr, nc))
                        seen.add((nr, nc))
        return result

    for r in range(height):
        for c in range(width):
            if result[r][c] == 2 and not visited[r][c]:
                comp = get_component([(r,c)])
                # Check if component touches a 1
                has_one = any(result[cr + dr][cc + dc] == 1 
                             for cr, cc in comp
                             for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)])
                if has_one:
                    for cr, cc in comp:
                        result[cr][cc] = 1

    return result

