    # Step 1: Converge row/col fills
    changed = True
    while changed:
        prev_result = [row[:] for row in result]

        rows_to_fill = set()
        cols_to_fill = set()

        for r in range(height):
            cnt = sum(1 for c in range(width) if result[r][c] == 1)
            if cnt >= 2:
                rows_to_fill.add(r)

        for c in range(width):
            cnt = sum(1 for r in range(height) if result[r][c] == 1)
            if cnt >= 2:
                cols_to_fill.add(c)

        for r in sorted(rows_to_fill):
            for c in range(width):
                if result[r][c] != 1:
                    result[r][c] = 1

        for c in sorted(cols_to_fill):
            for r in range(height):
                if result[r][c] != 1:
                    result[r][c] = 1

        changed = False
        for r in range(height):
            for c in range(width):
                if prev_result[r][c] != result[r][c]:
                    changed = True
                    break
            if changed:
                break

    # Step 2: Convert 2-components adjacent to 1s
    visited = [[False]*width for _ in range(height)]

    def bfs_component(seed_cells):
        """Get all connected 2s starting from seed_cells"""
        comp = list(seed_cells)
        queue = list(seed_cells)
        seen = set(seed_cells)

        idx = 0
        while idx < len(queue):
            r, c = queue[idx]
            idx += 1
            for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
                nr, nc = r+dr, c+dc
                if 0 <= nr < height and 0 <= nc < width:
                    if (nr, nc) not in seen and result[nr][nc] == 2:
                        seen.add((nr, nc))
                        queue.append((nr, nc))
                        comp.append((nr, nc))
        return comp

    # Find all components
    for r in range(height):
        for c in range(width):
            if result[r][c] == 2 and not visited[r][c]:
                comp = bfs_component([(r,c)])
                for cr, cc in comp:
                    visited[cr][cc] = True

                # Check if component touches a 1
                has_one = any(result[cr + dr][cc + dc] == 1 
                             for cr, cc in comp
                             for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)])

                if has_one:
                    for cr, cc in comp:
