            cols_with_ones = [c for c in range(width) if result[r][c] == 1]
            if len(cols_with_ones) >= 2:
                # Fill entire row segment between min and max
                min_c, max_c = min(cols_with_ones), max(cols_with_ones)
                for c in range(min_c, max_c + 1):
                    result[r][c] = 1

        # For each col with a marker, extend vertically
        for c in range(width):
            rows_with_ones = [r for r in range(height) if result[r][c] == 1]
            if len(rows_with_ones) >= 2:
                min_r, max_r = min(rows_with_ones), max(rows_with_ones)
                for r in range(min_r, max_r + 1):
                    result[r][c] = 1

        current_size = len(set((r,c) for r in range(height) for c in range(width) if result[r][c] == 1))
        print(f"Iteration {iteration}: created {current_size} ones")

        if current_size == prev_size:
            break

    return result

